package com.randbox.randombox.network;
import net.minecraft.core.BlockPos;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.level.block.entity.ChestBlockEntity;import net.minecraftforge.network.NetworkEvent;import java.util.function.Supplier;
public record FinishPacket(BlockPos pos){public static void encode(FinishPacket p,FriendlyByteBuf b){b.writeBlockPos(p.pos);}public static FinishPacket decode(FriendlyByteBuf b){return new FinishPacket(b.readBlockPos());}public static void handle(FinishPacket p,Supplier<NetworkEvent.Context>s){ServerPlayer player=s.get().getSender();s.get().enqueueWork(()->{if(player!=null&&player.distanceToSqr(p.pos.getX()+.5,p.pos.getY()+.5,p.pos.getZ()+.5)<64&&player.level().getBlockEntity(p.pos) instanceof ChestBlockEntity chest)player.openMenu(chest);});s.get().setPacketHandled(true);}}
